var b = GameState.create_snapshot()
var all = []
for uid in b.units:
	for m in b.units[uid].get("models", []):
		if m.get("alive", true) and m.get("position") != null:
			all.append(m)
for i in range(all.size()):
	for j in range(i + 1, all.size()):
		if Measurement.models_overlap(all[i], all[j]):
			return false
return true

var b = GameState.create_snapshot()
var cust = b.units["U_CUSTODIAN_GUARD_T"].models
var n = 0
for uid in ["U_BOYZ_T", "U_WARBOSS_T"]:
	for m in b.units[uid].models:
		if not m.get("alive", true):
			continue
		for c in cust:
			if Measurement.model_to_model_distance_inches(m, c) <= RulesEngine.BASE_CONTACT_TOLERANCE_INCHES:
				n += 1
				break
return str(n) + " of " + str(cust.size())

var b = GameState.create_snapshot()
var alive = 0
for m in b.units["U_BOYZ_T"].models:
	if m.get("alive", true):
		alive += 1
return str(RulesEngine.get_eligible_melee_model_indices(b.units["U_BOYZ_T"], b).size()) + "/" + str(alive)

var wb = GameState.get_unit("U_WARBOSS_T")
var p = wb.models[0].position
var want = Vector2(p.x, p.y) if p is Dictionary else p
var layer = tree.root.get_node("/root/Main/BoardRoot/TokenLayer")
var n = 0
for c in layer.get_children():
	if c.position.distance_to(want) < 1.0:
		n += 1
return n

var b = GameState.create_snapshot()
var cust = b.units["U_CUSTODIAN_GUARD_T"].models
var out_of_er = 0
var reachable = 0
for id in ["m6", "m7", "m8", "m9", "m10"]:
	for m in b.units["U_BOYZ_T"].models:
		if str(m.id) != id:
			continue
		var best = 999.0
		for c in cust:
			best = min(best, Measurement.model_to_model_distance_inches(m, c))
		if best > GameConstants.engagement_range_inches():
			out_of_er += 1
		if best <= 3.0:
			reachable += 1
return str(out_of_er) + " out of ER, " + str(reachable) + " within 3in"

