var lst = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightSelectionPanel/UnitList")
var rows = []
for c in lst.get_children():
	if c is Button:
		rows.append(c.name + "=" + c.text)
return ",".join(rows)

for c in tree.root.get_children():
	if c is AcceptDialog and c.visible and str(c.title).begins_with("Epic Challenge"):
		for btn in c.find_children("*", "Button", true, false):
			if btn.text == "Decline":
				btn.pressed.emit()
				return "declined"
return "no epic dialog"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var wl = d.get_node("Content/WeaponList")
var tl = d.get_node("Content/TargetList")
if wl.item_count == 0 or tl.item_count == 0:
	return "empty lists"
var want = -1
var labels = []
for i in range(wl.item_count):
	labels.append(str(wl.get_item_text(i)))
	if str(wl.get_item_text(i)).begins_with("Big choppa"):
		want = i
if want < 0:
	return "no Big choppa offered"
wl.select(want)
wl.item_selected.emit(want)
tl.select(0)
tl.item_selected.emit(0)
return str(wl.get_item_text(want)) + " | " + str(labels)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append(str(a.get("attacker", "?")) + ":" + str(a.get("weapon", "?")) + ":" + str((a.get("models", []) as Array).size()))
out.sort()
return ",".join(out)

